def SupportAssignmentLocallyConstant (f : Set ℕ → ℕ → ℂ) : Prop :=
  ∀ M : Set ℕ, M.Infinite → ∃ r : ℕ, ∀ Q : Set ℕ, Q.Infinite →
    (∀ i : ℕ, i < r → (i ∈ M ↔ i ∈ Q)) → f Q = f M

